#include <iostream>#include <cmath>#include "../bs_pricer.hpp"bool approx_equal(double a, double b, double tolerance = 1e-6) {    return std::abs(a - b) < tolerance;}// Numerical Deltadouble numerical_delta(    double S,    double K,    double T,    double r,    double vol,    double h = 0.0001) {    PriceResult price_up =        bs_price(S + h, K, T, r, vol, "call");    PriceResult price_down =        bs_price(S - h, K, T, r, vol, "call");    return (price_up.price - price_down.price) / (2.0 * h);}// Numerical Gammadouble numerical_gamma(    double S,    double K,    double T,    double r,    double vol,    double h = 0.0001) {    PriceResult price_up =        bs_price(S + h, K, T, r, vol, "call");    PriceResult price_mid =        bs_price(S, K, T, r, vol, "call");    PriceResult price_down =        bs_price(S - h, K, T, r, vol, "call");    return (price_up.price            - 2.0 * price_mid.price            + price_down.price)           / (h * h);}// Numerical Vega// Expressed per 1 percentage-point volatility changedouble numerical_vega(    double S,    double K,    double T,    double r,    double vol,    double h = 0.0001) {    PriceResult vol_up =        bs_price(S, K, T, r, vol + h, "call");    PriceResult vol_down =        bs_price(S, K, T, r, vol - h, "call");    return (vol_up.price - vol_down.price)           / (2.0 * h)           / 100.0;}// Numerical Theta// Expressed per daydouble numerical_theta(    double S,    double K,    double T,    double r,    double vol,    double h = 0.0001) {    PriceResult time_up =        bs_price(S, K, T + h, r, vol, "call");    PriceResult time_down =        bs_price(S, K, T - h, r, vol, "call");    double theta_per_year =        (time_down.price - time_up.price)        / (2.0 * h);    return theta_per_year / 365.0;}// Numerical Rho// Expressed per 1 percentage-point interest-rate changedouble numerical_rho(    double S,    double K,    double T,    double r,    double vol,    double h = 0.0001) {    PriceResult rate_up =        bs_price(S, K, T, r + h, vol, "call");    PriceResult rate_down =        bs_price(S, K, T, r - h, vol, "call");    return (rate_up.price - rate_down.price)           / (2.0 * h)           / 100.0;}int main() {    // Test inputs    double S = 100.0;    double K = 105.0;    double T = 0.5;    double r = 0.045;    double vol = 0.25;    // Test 1: Call price    PriceResult call_result =        bs_price(S, K, T, r, vol, "call");    double expected_call_price = 5.88364;    if (!approx_equal(            call_result.price,            expected_call_price        )) {        std::cerr << "TEST FAILED: Call price\n";        std::cerr << "Expected: "                  << expected_call_price << "\n";        std::cerr << "Got: "                  << call_result.price << "\n";        return 1;    }    std::cout << "TEST PASSED: Call price\n";    // Test 2: Put price    PriceResult put_result =        bs_price(S, K, T, r, vol, "put");    double expected_put_price = 8.54752;    if (!approx_equal(            put_result.price,            expected_put_price        )) {        std::cerr << "TEST FAILED: Put price\n";        std::cerr << "Expected: "                  << expected_put_price << "\n";        std::cerr << "Got: "                  << put_result.price << "\n";        return 1;    }    std::cout << "TEST PASSED: Put price\n";    // Test 3: Put-call parity    double parity_difference =        call_result.price        - put_result.price        - (S - K * std::exp(-r * T));    if (!approx_equal(            parity_difference,            0.0,            1e-5        )) {        std::cerr << "TEST FAILED: Put-call parity\n";        std::cerr << "Parity difference: "                  << parity_difference << "\n";        return 1;    }    std::cout << "TEST PASSED: Put-call parity\n";    // Calculate analytical Greeks    Greeks greeks =        bs_greeks(S, K, T, r, vol, "call");    // Test 4: Delta    double numerical_delta_value =        numerical_delta(S, K, T, r, vol);    if (!approx_equal(            greeks.delta,            numerical_delta_value,            1e-5        )) {        std::cerr << "TEST FAILED: Delta validation\n";        std::cerr << "Analytical Delta: "                  << greeks.delta << "\n";        std::cerr << "Numerical Delta: "                  << numerical_delta_value << "\n";        return 1;    }    std::cout << "TEST PASSED: Delta validation\n";    // Test 5: Gamma    double numerical_gamma_value =        numerical_gamma(S, K, T, r, vol);    if (!approx_equal(            greeks.gamma,            numerical_gamma_value,            1e-4        )) {        std::cerr << "TEST FAILED: Gamma validation\n";        std::cerr << "Analytical Gamma: "                  << greeks.gamma << "\n";        std::cerr << "Numerical Gamma: "                  << numerical_gamma_value << "\n";        return 1;    }    std::cout << "TEST PASSED: Gamma validation\n";    // Test 6: Vega    double numerical_vega_value =        numerical_vega(S, K, T, r, vol);    if (!approx_equal(            greeks.vega,            numerical_vega_value,            1e-4        )) {        std::cerr << "TEST FAILED: Vega validation\n";        std::cerr << "Analytical Vega: "                  << greeks.vega << "\n";        std::cerr << "Numerical Vega: "                  << numerical_vega_value << "\n";        return 1;    }    std::cout << "TEST PASSED: Vega validation\n";    // Test 7: Theta    double numerical_theta_value =        numerical_theta(S, K, T, r, vol);    if (!approx_equal(            greeks.theta,            numerical_theta_value,            1e-4        )) {        std::cerr << "TEST FAILED: Theta validation\n";        std::cerr << "Analytical Theta: "                  << greeks.theta << "\n";        std::cerr << "Numerical Theta: "                  << numerical_theta_value << "\n";        return 1;    }    std::cout << "TEST PASSED: Theta validation\n";    // Test 8: Rho    double numerical_rho_value =        numerical_rho(S, K, T, r, vol);    if (!approx_equal(            greeks.rho,            numerical_rho_value,            1e-4        )) {        std::cerr << "TEST FAILED: Rho validation\n";        std::cerr << "Analytical Rho: "                  << greeks.rho << "\n";        std::cerr << "Numerical Rho: "                  << numerical_rho_value << "\n";        return 1;    }    std::cout << "TEST PASSED: Rho validation\n";    // Final result    std::cout << "\nAll tests passed!\n";    return 0;}